  const tasksFilePath = writeTasks(tempDir, {
    title: 'Tasks',
    componentsSection: [],
    notesSection: [],
    tasks: [
      { id: 'T-001', title: 'Design API', status: 'design', completed: null, externalId: 'github:issue:11' }
