      title: 'Design API',
      body: 'body',
      state: 'open',
      labels: [],
      milestone: null,
      html_url: 'https://example.test/11',
      closed_at: null,
      updated_at: '2026-02-03T00:00:00Z'
    },
    {
      number: 12,
      node_id: 'I_12',
      title: 'QA pass',
      body: 'body',
      state: 'open',
      labels: [],
      milestone: null,
      html_url: 'https://example.test/12',
      closed_at: null,
      updated_at: '2026-02-03T00:00:00Z'
